"""
Regenerate the SYNTHETIC test fixtures in this directory.

Everything written here is fabricated. The values are chosen so the expected answers
are computable by hand (see the comments), not to resemble any system's behaviour.
Run from the analysis directory:  python3 tests/fixtures/make_fixtures.py

Every generated file carries a NOT A MEASUREMENT banner in its own comment syntax so
it cannot be mistaken for output of a real run.
"""

import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from pipeline import hdr  # noqa: E402

HERE = Path(__file__).resolve().parent
BANNER = "SYNTHETIC FIXTURE - NOT A MEASUREMENT - generated by make_fixtures.py"

WRK2_PERCENTILES = [50.0, 75.0, 90.0, 99.0, 99.9, 99.99, 99.999, 100.0]


def format_wrk2_time_us(microseconds: float) -> str:
    """wrk2 prints a unit-scaled fixed-point value. Same shape, not the same code."""
    if microseconds < 1000:
        return f"{microseconds:.2f}us"
    if microseconds < 1_000_000:
        return f"{microseconds / 1000.0:.2f}ms"
    if microseconds < 60_000_000:
        return f"{microseconds / 1_000_000.0:.2f}s"
    return f"{microseconds / 60_000_000.0:.2f}m"


def build_known_histogram() -> hdr.HdrHistogram:
    """
    100000 values in microseconds, constructed so the order statistics are exact.

    index 49999 (the 50000th value) = 1050  -> p50  reads back as 1050 us
    index 98999 (the 99000th value) = 12340 -> p99  reads back as 12343 us
                                               (bucket 3, width 8, 12336..12343)
    """
    values = np.empty(100000, dtype=np.int64)
    values[0:49999] = np.linspace(100, 1049, 49999).astype(np.int64)
    values[49999] = 1050
    values[50000:98999] = np.linspace(1051, 12335, 48999).astype(np.int64)
    values[98999] = 12340
    # A smooth tail, not a cliff. A discontinuity at exactly the 99th percentile
    # would make the percentile-spectrum bracket around p99 span a factor of two,
    # which says more about the fixture than about the parser.
    values[99000:100000] = np.linspace(12400, 30000, 1000).astype(np.int64)

    h = hdr.HdrHistogram(1, 60 * 1000 * 1000, 3)
    h.record_values(values)
    assert h.total_count == 100000
    assert h.get_value_at_percentile(50.0) == 1050
    assert h.get_value_at_percentile(99.0) == 12343
    return h


def build_uncorrected_histogram(base: hdr.HdrHistogram) -> hdr.HdrHistogram:
    """Same shape, halved. Stands in for wrk2's uncorrected series, which is lower."""
    h = hdr.HdrHistogram(1, 60 * 1000 * 1000, 3)
    for value, count in base.recorded_values():
        h.record_value(max(1, value // 2), count)
    return h


def write_wrk2_fixture(corrected, uncorrected) -> None:
    lines = [
        f"#[{BANNER}]",
        "#[Not produced by wrk2. Hand-generated to exercise the parser.]",
        "Running 30s test @ http://synthetic.invalid/api/resource",
        "  2 threads and 16 connections",
        "  Thread calibration: mean lat.: 0.000ms, rate sampling interval: 0ms",
        "  Latency Distribution (HdrHistogram - Recorded Latency)",
    ]
    for p in WRK2_PERCENTILES:
        lines.append(f"{p:7.3f}%{format_wrk2_time_us(corrected.get_value_at_percentile(p)):>11s}")
    lines.append("")
    lines.append("  Latency Distribution (HdrHistogram - Uncorrected Latency)")
    for p in WRK2_PERCENTILES:
        lines.append(f"{p:7.3f}%{format_wrk2_time_us(uncorrected.get_value_at_percentile(p)):>11s}")
    lines.append("")
    lines.append("  Detailed Percentile spectrum:")
    # value_scale converts microseconds to milliseconds, as wrk2 does.
    lines.append(corrected.output_percentile_distribution(value_scale=1000.0)
                 .rstrip("\n"))
    lines.append("  100000 requests in 30.00s, 12.34MB read")
    lines.append("Requests/sec:   3333.33")
    (HERE / "SYNTHETIC_NOT_A_MEASUREMENT_wrk2.txt").write_text(
        "\n".join(lines) + "\n", encoding="utf-8")


def write_hlog_fixture() -> None:
    rng = np.random.default_rng(20260727)
    lines = [
        f"#[{BANNER}]",
        "#[StartTime: 0.000 (seconds since epoch)]",
        '"StartTimestamp","Interval_Length","Interval_Max",'
        '"Interval_Compressed_Histogram"',
    ]
    for i in range(3):
        h = hdr.HdrHistogram(1, 60 * 1000 * 1000, 3)
        samples = np.round(rng.lognormal(np.log(2000), 0.5, size=5000))
        h.record_values(samples.astype(np.int64) + 1)
        lines.append(f"Tag=SYNTHETIC,{float(i):.3f},1.000,"
                     f"{h.get_max_value() / 1000.0:.3f},{h.to_base64()}")
    (HERE / "SYNTHETIC_NOT_A_MEASUREMENT.hlog").write_text(
        "\n".join(lines) + "\n", encoding="utf-8")


def write_k6_fixture() -> None:
    """
    k6 --out json shape. Four http_req_duration points plus noise records.

    JSON has no comment syntax, so the banner rides in as a Metric record whose name
    says what this is.
    """
    records = [
        '{"type":"Metric","metric":"__SYNTHETIC_FIXTURE_NOT_A_MEASUREMENT__",'
        '"data":{"name":"__SYNTHETIC_FIXTURE_NOT_A_MEASUREMENT__","type":"trend"}}',
        '{"type":"Metric","metric":"http_req_duration",'
        '"data":{"name":"http_req_duration","type":"trend","contains":"time"}}',
        '{"type":"Point","metric":"vus",'
        '"data":{"time":"2026-01-01T00:00:00.000000000Z","value":10}}',
        '{"type":"Point","metric":"http_req_duration",'
        '"data":{"time":"2026-01-01T00:00:00.000000000Z","value":1.5,'
        '"tags":{"status":"200"}}}',
        '{"type":"Point","metric":"http_req_duration",'
        '"data":{"time":"2026-01-01T00:00:00.250000000Z","value":2.25,'
        '"tags":{"status":"200"}}}',
        '{"type":"Point","metric":"http_req_duration",'
        '"data":{"time":"2026-01-01T00:00:00.500000000Z","value":3.0,'
        '"tags":{"status":"200"}}}',
        '{"type":"Point","metric":"http_req_duration",'
        '"data":{"time":"2026-01-01T00:00:01.000000000Z","value":90.125,'
        '"tags":{"status":"200"}}}',
    ]
    (HERE / "SYNTHETIC_NOT_A_MEASUREMENT_k6.json").write_text(
        "\n".join(records) + "\n", encoding="utf-8")


def main() -> int:
    corrected = build_known_histogram()
    write_wrk2_fixture(corrected, build_uncorrected_histogram(corrected))
    write_hlog_fixture()
    write_k6_fixture()
    print("wrote SYNTHETIC fixtures to", HERE)
    print("  p50 =", corrected.get_value_at_percentile(50.0), "us")
    print("  p99 =", corrected.get_value_at_percentile(99.0), "us")
    print("  max =", corrected.get_max_value(), "us")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
